#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

void push(Node*& head, int value) {
    Node* n = new Node();
    n->data = value;
    n->next = head;
    head = n;
}

void deleteFront(Node*& head) {
    if (head == NULL) return;
    Node* temp = head;
    head = head->next;
    delete temp;
}

int main() {
    Node* head = NULL;
    push(head, 30);
    push(head, 20);
    push(head, 10);
    deleteFront(head);
    deleteFront(head);
    return 0;
}
